#!/usr/bin/env bash
# Copyright 2026, Battelle Energy Alliance, LLC, ALL RIGHTS RESERVED
#
# Generate iso15118/evcc/asn1/esdp_definitions.asn from the ISO/PAS 15118-202
# ESDP schema. The generated file is not committed; run this once after
# cloning (and before importing iso15118.evcc.asn1.esdp_asn1_main).
#
# Steps:
#   1. Download ESDPExtensions.asn from the ISO server (kept as *.orig).
#   2. Rejoin the ".<newline>&" breaks in the published file, which otherwise
#      make "EXTENSION.&id" unparseable.
#   3. Replace the EXTENSION class / ExtensionSet and the ESDPExtensions /
#      ESDPExtension envelopes with the plain OCTET STRING form asn1tools can
#      handle (see UPSTREAM_NOTE.md).
#
# Requires: bash, curl, perl, awk. Run from anywhere.
#
# Usage:
#   ./generate_esdp_definitions.sh
#   ESDP_ASN_SRC=/path/to/ESDPExtensions.asn ./generate_esdp_definitions.sh   # skip download
#
set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
ESDP_URL="https://standards.iso.org/iso/pas/15118/-202/ed-1/en/ESDPExtensions.asn"
OUT="${SCRIPT_DIR}/esdp_definitions.asn"
WORK="$(mktemp -d)"
trap 'rm -rf "${WORK}"' EXIT

ORIG="${WORK}/ESDPExtensions.asn.orig"
NORM="${WORK}/esdp_extensions.asn"

if [ -n "${ESDP_ASN_SRC:-}" ]; then
    cp -f "${ESDP_ASN_SRC}" "${ORIG}"
else
    echo ">> fetching ${ESDP_URL}"
    curl -fSL --retry 3 --retry-delay 2 -o "${ORIG}" "${ESDP_URL}"
fi

if [ ! -s "${ORIG}" ] || ! grep -q "DEFINITIONS" "${ORIG}"; then
    echo "ERROR: ${ORIG} is empty or does not look like an ASN.1 module" >&2
    exit 1
fi

# Step 2: rejoin split field references.
cp -f "${ORIG}" "${NORM}"
perl -0777 -pi -e 's/\.\s*\n\s*&/.&/g' "${NORM}"
if grep -qE "EXTENSION\.\s*$" "${NORM}"; then
    echo "ERROR: broken EXTENSION.& references remain; upstream format may have changed" >&2
    exit 1
fi

# Step 3: derive the asn1tools-compatible schema.
awk -v module_name=ESDPExtensionsCodegen \
    -v container_type=ESDPExtensions \
    -v list_field=esdpExtensionsList \
    -v item_type=ESDPExtension '
    /^[A-Za-z0-9-]+ DEFINITIONS/ {
        print module_name " DEFINITIONS AUTOMATIC TAGS ::= BEGIN"
        next
    }
    $0 ~ "^" container_type " ::= SEQUENCE" {
        print container_type " ::= SEQUENCE {"
        print "  " list_field " SEQUENCE (SIZE (1..MAX)) OF " item_type ","
        print "  ..."
        print "}"
        skip_container = 1
        next
    }
    skip_container { if ($0 ~ /^}/) { skip_container = 0 } next }
    $0 ~ "^" item_type " ::= SEQUENCE" {
        print item_type " ::= SEQUENCE {"
        print "  extensionID     OCTET STRING (SIZE (16)),"
        print "  extensionValue  OCTET STRING,"
        print "  ..."
        print "}"
        skip_item = 1
        next
    }
    skip_item { if ($0 ~ /^}/) { skip_item = 0 } next }
    /^EXTENSION ::= CLASS/ { skip_class = 1; next }
    skip_class { if ($0 ~ /WITH SYNTAX/) { skip_class = 0 } next }
    /^ExtensionSet EXTENSION ::= \{/ { skip_set = 1; next }
    skip_set { if ($0 ~ /^}/) { skip_set = 0 } next }
    { print }
' "${NORM}" > "${WORK}/body.asn"

{
    cat <<'HEADER'
-- GENERATED by generate_esdp_definitions.sh -- do not edit or commit.
-- Derived from ISO/PAS 15118-202:2025 ESDPExtensions.asn:
-- https://standards.iso.org/iso/pas/15118/-202/ed-1/en/ESDPExtensions.asn
-- See UPSTREAM_NOTE.md in this directory for the intentional deviations.

HEADER
    cat "${WORK}/body.asn"
} > "${OUT}"

echo ">> wrote ${OUT}"
